<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Conway's Game of Life</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    background: #0d1117;
    color: #e6edf3;
    font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
    gap: 1.25rem;
    padding: 1.5rem;
  }

  h1 {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    color: #58a6ff;
    text-shadow: 0 0 18px rgba(88, 166, 255, 0.35);
  }

  .subtitle {
    font-size: 0.85rem;
    color: #8b949e;
    margin-top: -0.6rem;
  }

  #life {
    width: 480px;
    height: 480px;
    max-width: min(480px, 92vw);
    max-height: min(480px, 92vw);
    background: #161b22;
    border: 2px solid #30363d;
    border-radius: 12px;
    box-shadow:
      0 0 0 1px rgba(88, 166, 255, 0.08),
      0 12px 40px rgba(0, 0, 0, 0.45),
      inset 0 0 60px rgba(88, 166, 255, 0.04);
    cursor: crosshair;
    touch-action: none;
  }

  .controls {
    display: flex;
    flex-wrap: wrap;
    gap: 0.6rem;
    justify-content: center;
    align-items: center;
  }

  button {
    appearance: none;
    border: 1px solid #30363d;
    background: #21262d;
    color: #e6edf3;
    font-size: 0.9rem;
    font-weight: 600;
    padding: 0.55rem 1.1rem;
    border-radius: 8px;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s, transform 0.1s, box-shadow 0.15s;
  }

  button:hover {
    background: #30363d;
    border-color: #58a6ff;
    box-shadow: 0 0 12px rgba(88, 166, 255, 0.2);
  }

  button:active {
    transform: scale(0.96);
  }

  button#play.playing {
    background: #238636;
    border-color: #2ea043;
    color: #fff;
  }

  button#play.playing:hover {
    background: #2ea043;
  }

  button#clear:hover {
    border-color: #f85149;
    box-shadow: 0 0 12px rgba(248, 81, 73, 0.25);
  }

  button#random:hover {
    border-color: #d2a8ff;
    box-shadow: 0 0 12px rgba(210, 168, 255, 0.25);
  }

  .gen {
    font-size: 0.8rem;
    color: #8b949e;
    font-variant-numeric: tabular-nums;
  }

  .gen span {
    color: #58a6ff;
    font-weight: 600;
  }
</style>
</head>
<body>
  <h1>Conway's Game of Life</h1>
  <p class="subtitle">B3/S23 · paint cells · watch them dance</p>
  <canvas id="life" width="480" height="480"></canvas>
  <div class="controls">
    <button id="step" type="button">Step</button>
    <button id="play" type="button">Play</button>
    <button id="random" type="button">Random</button>
    <button id="clear" type="button">Clear</button>
  </div>
  <p class="gen">Generation <span id="genCount">0</span></p>

<script>
(function () {
  const COLS = 48;
  const ROWS = 48;
  const canvas = document.getElementById('life');
  const ctx = canvas.getContext('2d');
  const genEl = document.getElementById('genCount');

  // Backing store matches CSS size for crisp pixels
  const cssSize = 480;
  canvas.width = cssSize;
  canvas.height = cssSize;

  const cellW = cssSize / COLS;
  const cellH = cssSize / ROWS;

  let grid = new Uint8Array(COLS * ROWS);
  let generation = 0;
  let playing = false;
  let timer = null;
  const PLAY_MS = 120;

  function idx(x, y) {
    return y * COLS + x;
  }

  function get(x, y) {
    if (x < 0 || y < 0 || x >= COLS || y >= ROWS) return 0;
    return grid[idx(x, y)];
  }

  function set(x, y, v) {
    if (x < 0 || y < 0 || x >= COLS || y >= ROWS) return;
    grid[idx(x, y)] = v ? 1 : 0;
  }

  function countNeighbors(x, y) {
    let n = 0;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        n += get(x + dx, y + dy);
      }
    }
    return n;
  }

  function step() {
    const next = new Uint8Array(COLS * ROWS);
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        const alive = grid[idx(x, y)];
        const n = countNeighbors(x, y);
        // B3/S23
        if (alive) {
          next[idx(x, y)] = (n === 2 || n === 3) ? 1 : 0;
        } else {
          next[idx(x, y)] = (n === 3) ? 1 : 0;
        }
      }
    }
    grid = next;
    generation++;
    genEl.textContent = String(generation);
    draw();
  }

  function clear() {
    grid.fill(0);
    generation = 0;
    genEl.textContent = '0';
    draw();
  }

  function randomize() {
    for (let i = 0; i < grid.length; i++) {
      grid[i] = Math.random() < 0.28 ? 1 : 0;
    }
    generation = 0;
    genEl.textContent = '0';
    draw();
  }

  function draw() {
    // Background
    ctx.fillStyle = '#161b22';
    ctx.fillRect(0, 0, cssSize, cssSize);

    // Subtle grid lines
    ctx.strokeStyle = 'rgba(48, 54, 61, 0.55)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = 0; x <= COLS; x++) {
      const px = Math.round(x * cellW) + 0.5;
      ctx.moveTo(px, 0);
      ctx.lineTo(px, cssSize);
    }
    for (let y = 0; y <= ROWS; y++) {
      const py = Math.round(y * cellH) + 0.5;
      ctx.moveTo(0, py);
      ctx.lineTo(cssSize, py);
    }
    ctx.stroke();

    // Live cells
    const pad = 1;
    for (let y = 0; y < ROWS; y++) {
      for (let x = 0; x < COLS; x++) {
        if (!grid[idx(x, y)]) continue;
        const px = x * cellW;
        const py = y * cellH;
        // Soft glow
        const g = ctx.createRadialGradient(
          px + cellW / 2, py + cellH / 2, 0,
          px + cellW / 2, py + cellH / 2, cellW * 0.7
        );
        g.addColorStop(0, '#79c0ff');
        g.addColorStop(0.55, '#58a6ff');
        g.addColorStop(1, '#1f6feb');
        ctx.fillStyle = g;
        ctx.fillRect(px + pad, py + pad, cellW - pad * 2, cellH - pad * 2);
      }
    }
  }

  // Painting
  let painting = false;
  let paintValue = 1;

  function cellFromEvent(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const cx = (e.clientX - rect.left) * scaleX;
    const cy = (e.clientY - rect.top) * scaleY;
    const x = Math.floor(cx / cellW);
    const y = Math.floor(cy / cellH);
    return { x, y };
  }

  function paintAt(e) {
    const { x, y } = cellFromEvent(e);
    if (x < 0 || y < 0 || x >= COLS || y >= ROWS) return;
    set(x, y, paintValue);
    draw();
  }

  canvas.addEventListener('mousedown', (e) => {
    if (e.button !== 0) return;
    painting = true;
    const { x, y } = cellFromEvent(e);
    // Toggle: if cell is alive, start painting dead; else paint alive
    paintValue = get(x, y) ? 0 : 1;
    paintAt(e);
  });

  canvas.addEventListener('mousemove', (e) => {
    if (!painting) return;
    paintAt(e);
  });

  window.addEventListener('mouseup', () => {
    painting = false;
  });

  canvas.addEventListener('mouseleave', () => {
    // keep painting if button held and re-enter — handled via window mouseup
  });

  // Touch support
  canvas.addEventListener('touchstart', (e) => {
    e.preventDefault();
    const t = e.touches[0];
    painting = true;
    const fake = { clientX: t.clientX, clientY: t.clientY };
    const { x, y } = cellFromEvent(fake);
    paintValue = get(x, y) ? 0 : 1;
    paintAt(fake);
  }, { passive: false });

  canvas.addEventListener('touchmove', (e) => {
    e.preventDefault();
    if (!painting) return;
    const t = e.touches[0];
    paintAt({ clientX: t.clientX, clientY: t.clientY });
  }, { passive: false });

  canvas.addEventListener('touchend', () => {
    painting = false;
  });

  // Controls
  const btnStep = document.getElementById('step');
  const btnPlay = document.getElementById('play');
  const btnRandom = document.getElementById('random');
  const btnClear = document.getElementById('clear');

  btnStep.addEventListener('click', () => step());

  function stopPlay() {
    playing = false;
    btnPlay.textContent = 'Play';
    btnPlay.classList.remove('playing');
    if (timer !== null) {
      clearInterval(timer);
      timer = null;
    }
  }

  function startPlay() {
    playing = true;
    btnPlay.textContent = 'Pause';
    btnPlay.classList.add('playing');
    timer = setInterval(() => step(), PLAY_MS);
  }

  btnPlay.addEventListener('click', () => {
    if (playing) stopPlay();
    else startPlay();
  });

  btnRandom.addEventListener('click', () => {
    randomize();
  });

  btnClear.addEventListener('click', () => {
    clear();
  });

  // Public API
  window.life = {
    w: COLS,
    h: ROWS,
    get: get,
    set: function (x, y, v) {
      set(x, y, v);
      draw();
    },
    step: step,
    clear: clear
  };

  draw();
})();
</script>
</body>
</html>
